import { canonicalApplicationBytes } from "./canonical-application.js";
import { parseFlowSpec } from "./flowspec.js";
import { resolveFeltDBModule } from "./module.js";
const secretValue = /(?:sk_(?:live|test)_|whsec_|fdb_(?:live|control)_|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----)/i;
const AUTOMATIC_PLANNING_CONFIDENCE = 0.8;
function safe(value) {
    if (typeof value === "string")
        return secretValue.test(value) ? "[REDACTED]" : value.slice(0, 500);
    if (Array.isArray(value))
        return value.slice(0, 50).map(safe);
    if (value && typeof value === "object")
        return Object.fromEntries(Object.entries(value)
            .slice(0, 50)
            .map(([key, child]) => [
            key,
            /password|token|credential|private.?key|secret.?value/i.test(key)
                ? "[REDACTED]"
                : safe(child),
        ]));
    return value;
}
async function hash(value) {
    const bytes = canonicalApplicationBytes(value);
    const digest = await crypto.subtle.digest("SHA-256", bytes.slice().buffer);
    return `sha256:${Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("")}`;
}
async function evidence(source, claim, value, source_ref, authority) {
    const normalized = {
        source,
        claim: claim.slice(0, 200),
        value: safe(value),
        source_ref: source_ref.slice(0, 500),
        authority,
    };
    return { id: `ev_${(await hash(normalized)).slice(7, 23)}`, ...normalized };
}
/** Deterministic, bounded understanding stage. It accepts structured observations, never raw repository contents. */
export async function collectApplicationUnderstanding(input) {
    const spec = parseFlowSpec(input.currentFlow);
    const collected = [];
    collected.push(await evidence("canonical_contract", "application.contract", {
        version: input.snapshot.contract_version,
        hash: input.snapshot.contract_hash,
    }, "contract", "authoritative"));
    collected.push(await evidence("feltdb.flow", "application.flow", { app: spec.app, version: spec.version }, "feltdb.flow", "authoritative"));
    for (const collection of spec.collections) {
        collected.push(await evidence("schema", `schema.collection.${collection.name}`, {
            fields: collection.fields.map((field) => ({
                name: field.name,
                type: field.type,
                optional: field.optional,
            })),
        }, `schema.collections.${collection.name}`, "authoritative"));
        for (const field of collection.fields.filter((field) => field.type.startsWith("ref ")))
            collected.push(await evidence("schema", `schema.relationship.${collection.name}.${field.name}`, `${collection.name}.${field.name} -> ${field.type.slice(4)}`, `schema.collections.${collection.name}.fields.${field.name}`, "authoritative"));
    }
    for (const policy of spec.policies)
        collected.push(await evidence("policy", `policy.${policy.name}`, policy.statements, `policies.${policy.name}`, "authoritative"));
    for (const workflow of spec.workflows)
        collected.push(await evidence("workflow", `workflow.${workflow.name}`, workflow.steps.map((step) => ({
            name: step.name,
            statements: step.statements,
        })), `workflows.${workflow.name}`, "authoritative"));
    for (const agent of spec.agents)
        collected.push(await evidence("agent", `agent.${agent.name}`, agent.statements, `agents.${agent.name}`, "authoritative"));
    for (const capability of spec.capabilities)
        collected.push(await evidence("capability", `capability.${capability.name}`, capability.statements, `capabilities.${capability.name}`, "authoritative"));
    const resolvedModule = input.moduleIntent
        ? resolveFeltDBModule({
            name: input.moduleIntent.module,
            provider: input.moduleIntent.provider,
            version: input.moduleIntent.version,
        })
        : undefined;
    if (resolvedModule) {
        const module = resolvedModule;
        collected.push(await evidence("module", `module.${module.id}`, {
            id: module.id,
            provider: module.provider,
            version: module.version,
            models: module.models,
            capabilities: module.capabilities,
            reconciliation: module.reconciliation,
            authorization: module.authorization,
            configuration: module.configuration.map((value) => value.name),
            secrets: module.secrets.map((value) => value.name),
        }, `module:${module.id}@${module.version}`, "authoritative"));
    }
    for (const observation of (input.observations ?? []).slice(0, 50))
        collected.push(await evidence(observation.source, observation.claim, observation.value ?? true, observation.source_ref, "observed"));
    if (collected.length > 256)
        throw new Error("EVIDENCE_LIMIT_EXCEEDED");
    const createdAt = input.now ?? new Date().toISOString();
    const relationships = collected.filter((value) => value.claim.startsWith("schema.relationship."));
    const explicitOwner = resolvedModule
        ? spec.collections
            .find((value) => value.name === resolvedModule.placement.primary_application_model)
            ?.fields.find((value) => value.name === resolvedModule.placement.owner_field &&
            value.type.startsWith("ref "))
        : undefined;
    const candidates = [
        ...new Set(resolvedModule?.patterns.flatMap((value) => value.owner_candidates) ?? []),
    ].filter((candidate) => spec.collections.some((value) => value.name === candidate));
    const ownershipSupport = (candidate) => collected.filter((item) => String(item.value).endsWith(`-> ${candidate}`) ||
        (item.source === "repository" &&
            item.claim.includes(candidate.toLowerCase()) &&
            item.claim.endsWith("_boundary")));
    const inferences = [];
    const unknowns = [];
    const assumptions = [];
    if (resolvedModule) {
        const ownerClaim = resolvedModule.placement.owner_claim;
        if (explicitOwner) {
            const owner = explicitOwner.type.slice(4);
            const relationshipClaim = `schema.relationship.${resolvedModule.placement.primary_application_model}.${resolvedModule.placement.owner_field}`;
            const support = relationships.filter((value) => value.claim === relationshipClaim);
            inferences.push({
                id: `inf_${resolvedModule.id}_owner`,
                claim: ownerClaim,
                value: owner,
                confidence: 1,
                authority: "authoritative",
                evidence: support.map((value) => value.id),
                counter_evidence: [],
                reason: `${resolvedModule.placement.primary_application_model}.${resolvedModule.placement.owner_field} is explicitly declared by the application contract.`,
                created_at: createdAt,
            });
        }
        else {
            const ranked = candidates
                .map((candidate) => ({
                candidate,
                support: ownershipSupport(candidate),
            }))
                .sort((left, right) => right.support.length - left.support.length ||
                left.candidate.localeCompare(right.candidate));
            if (ranked[0]?.support.length &&
                ranked[0].support.length > (ranked[1]?.support.length ?? 0)) {
                const authoritativeCount = ranked[0].support.filter((value) => value.authority === "authoritative").length;
                const confidence = Math.round(Math.min(0.97, authoritativeCount ? 0.84 + authoritativeCount * 0.06 : 0.72) * 100) / 100;
                inferences.push({
                    id: `inf_${resolvedModule.id}_owner`,
                    claim: ownerClaim,
                    value: ranked[0].candidate,
                    confidence,
                    authority: "inferred",
                    evidence: ranked[0].support.map((value) => value.id),
                    counter_evidence: ranked
                        .slice(1)
                        .flatMap((value) => value.support.map((item) => item.id)),
                    reason: `${ranked[0].candidate} is the strongest existing application ownership boundary.`,
                    created_at: createdAt,
                });
                if (confidence >= AUTOMATIC_PLANNING_CONFIDENCE)
                    assumptions.push({
                        claim: `${resolvedModule.placement.primary_application_model}.${resolvedModule.placement.owner_field}`,
                        value: ranked[0].candidate,
                        based_on: `inf_${resolvedModule.id}_owner`,
                        confidence,
                    });
                else
                    unknowns.push({
                        claim: ownerClaim,
                        reason: `The strongest ownership inference has confidence ${confidence}, below the ${AUTOMATIC_PLANNING_CONFIDENCE} planning threshold.`,
                        resolution: "clarification_required",
                    });
            }
            else {
                unknowns.push({
                    claim: ownerClaim,
                    reason: `The contract does not establish a unique ${resolvedModule.id} ownership boundary.`,
                    resolution: "clarification_required",
                });
            }
        }
        if (!spec.modules?.some((value) => value.name === resolvedModule.id))
            unknowns.push({
                claim: `${resolvedModule.id}.existing_implementation`,
                reason: `${resolvedModule.name} is not installed in the canonical application contract.`,
                resolution: "evidence_required",
            });
    }
    for (const inference of inferences)
        if (inference.confidence > 0 && !inference.evidence.length)
            throw new Error(`CONFIDENCE_WITHOUT_EVIDENCE: ${inference.claim}`);
    const evidenceHash = await hash(collected);
    const completenessFindings = [
        {
            claim: "ownership",
            status: (inferences.length
                ? "complete"
                : unknowns.some((value) => value.resolution === "clarification_required")
                    ? "contradictory"
                    : "missing"),
            evidence: inferences.flatMap((value) => value.evidence),
        },
        {
            claim: "integration_boundary",
            status: (resolvedModule ? "complete" : "missing"),
            evidence: collected
                .filter((value) => value.source === "module")
                .map((value) => value.id),
        },
        {
            claim: "authorization",
            status: (spec.policies.length ||
                collected.some((value) => value.claim === "repository.authentication")
                ? "complete"
                : "partial"),
            evidence: collected
                .filter((value) => value.source === "policy" ||
                value.claim === "repository.authentication")
                .map((value) => value.id),
        },
        {
            claim: "state_placement",
            status: (candidates.length ? "complete" : "missing"),
            evidence: collected
                .filter((value) => value.source === "schema")
                .map((value) => value.id),
        },
        {
            claim: "workflow_mapping",
            status: (resolvedModule?.reconciliation.length
                ? "complete"
                : "missing"),
            evidence: collected
                .filter((value) => value.source === "module")
                .map((value) => value.id),
        },
        {
            claim: "ui_placement",
            status: (collected.some((value) => value.source === "repository")
                ? "partial"
                : "missing"),
            evidence: collected
                .filter((value) => value.source === "repository")
                .map((value) => value.id),
        },
    ];
    const weights = { complete: 1, partial: 0.5, missing: 0, contradictory: 0 };
    const completeness = {
        score: Math.round((completenessFindings.reduce((sum, value) => sum + weights[value.status], 0) /
            completenessFindings.length) *
            100),
        findings: completenessFindings,
    };
    const semantic = {
        version: 1,
        application: input.snapshot.application,
        intent: input.intent,
        evidence_hash: evidenceHash,
        inferences,
        unknowns,
        assumptions,
        completeness,
    };
    const fingerprint = {
        ...semantic,
        inferences: inferences.map(({ created_at: _createdAt, ...inference }) => inference),
    };
    return {
        ...semantic,
        evidence: collected,
        understanding_hash: await hash(fingerprint),
        created_at: createdAt,
    };
}
export function understandingInference(understanding, claim) {
    return understanding.inferences.find((value) => value.claim === claim);
}
export function understandingOwner(understanding, module) {
    const claim = module?.placement.owner_claim ?? "billing.owner";
    const inference = understandingInference(understanding, claim);
    if (!inference ||
        understanding.unknowns.some((value) => value.claim === claim))
        return undefined;
    if (inference.authority !== "authoritative" &&
        inference.confidence < AUTOMATIC_PLANNING_CONFIDENCE)
        return undefined;
    return String(inference.value);
}
